const input={gas:0,brake:0,hand:0,steer:0};const keys=new Set(),held=new Map();let steerPointer=null;function resetInput(){keys.clear();held.clear();steerPointer=null;Object.assign(input,{gas:0,brake:0,hand:0,steer:0});$('knob').style.transform='';document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));}
for(const button of document.querySelectorAll('[data-input]')){button.addEventListener('pointerdown',e=>{e.preventDefault();if(mode!=='race'&&mode!=='countdown')return;button.setPointerCapture(e.pointerId);held.set(e.pointerId,button.dataset.input);button.classList.add('held');updateInput();});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,e=>{held.delete(e.pointerId);if(![...held.values()].includes(button.dataset.input))button.classList.remove('held');updateInput();});}
function updateInput(){for(const [action,codes] of Object.entries({gas:['ArrowUp','KeyW'],brake:['ArrowDown','KeyS'],hand:['Space']}))input[action]=codes.some(c=>keys.has(c))||[...held.values()].includes(action)?1:0;if(steerPointer===null)input.steer=(keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0);}
function steering(e){const r=$('steer').getBoundingClientRect();input.steer=clamp((e.clientX-r.left-r.width/2)/(r.width*.35),-1,1);$('knob').style.transform=`translateX(${input.steer*35}px)`;}
$('steer').addEventListener('pointerdown',e=>{e.preventDefault();if(steerPointer!==null)return;steerPointer=e.pointerId;$('steer').setPointerCapture(e.pointerId);steering(e);});$('steer').addEventListener('pointermove',e=>{if(e.pointerId===steerPointer)steering(e);});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('steer').addEventListener(event,e=>{if(e.pointerId===steerPointer){steerPointer=null;input.steer=0;$('knob').style.transform='';updateInput();}});
