let audioCtx,engine,engineGain;function initAudio(){if(muted)return;try{if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();engine=audioCtx.createOscillator();engine.type='sawtooth';const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=340;engineGain=audioCtx.createGain();engineGain.gain.value=0;engine.connect(filter).connect(engineGain).connect(audioCtx.destination);engine.start();}audioCtx.resume();}catch{}}
function sound(power=10,beep=false){if(!audioCtx||muted)return;const gain=audioCtx.createGain();gain.connect(audioCtx.destination);gain.gain.setValueAtTime(beep?.08:clamp(power/130,0,.3),audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+(beep?.16:.32));if(beep){const osc=audioCtx.createOscillator();osc.frequency.value=power;osc.connect(gain);osc.start();osc.stop(audioCtx.currentTime+.18);osc.onended=()=>gain.disconnect();}else{const buf=audioCtx.createBuffer(1,audioCtx.sampleRate*.3,audioCtx.sampleRate),data=buf.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/data.length*4);const src=audioCtx.createBufferSource();src.buffer=buf;const f=audioCtx.createBiquadFilter();f.frequency.value=900;src.connect(f).connect(gain);src.start();src.onended=()=>{f.disconnect();gain.disconnect();};}}
