$('start').onclick=start;$('retry').onclick=start;$('camera').onclick=()=>{view=(view+1)%3;};let previousMode='race';function togglePause(){if(mode==='race'||mode==='countdown'){previousMode=mode;mode='paused';resetInput();$('result-kicker').textContent='PAUSED';$('result-title').textContent='一時停止';$('result-detail').textContent=world.mode==='racing'?'4周。衝突点＋1周400点＋完走順位ボーナスで総合順位を決定。1位3500点、2位2900点、3位2400点。側面スピンは200点、撃破は500点。先頭ゴール後22秒で終了。':'側面を狙い、正面のエンジンを守ろう。22秒間接触がないと耐久力が減り始めます。';$('race-results').classList.add('hidden');$('result-stats').innerHTML='';$('resume').classList.remove('hidden');$('modal').classList.remove('hidden');}else if(mode==='paused'){mode=previousMode;$('modal').classList.add('hidden');initAudio();}}
