function finish(){if(resultShown)return;resultShown=true;mode='result';resetInput();if(world.mode==='racing'){finishRacing();return;}const p=world.cars[0],place=p.dead?world.cars.filter(c=>!c.dead||c.wreckAt>p.wreckAt).length+1:ranking(world).findIndex(c=>c.id===0)+1;let best=0;try{best=Number(localStorage.getItem('break-cars-best')||0);if(p.score>best)localStorage.setItem('break-cars-best',String(p.score));}catch{}$('result-kicker').textContent=place===1&&!p.dead?'COLOSSEUM CHAMPION':p.dead?'WRECKED':'TIME UP';$('result-title').textContent=place===1&&!p.dead?(world.time>=DURATION?'SCORE CHAMPION':'LAST CAR STANDING'):`${place}位 / ${COUNT}台`;$('result-detail').textContent=p.dead?'マシンは大破。次は側面を狙って反撃しよう。':world.time>=DURATION?'タイムアップ。生存車の衝突スコアで順位を決定。':'アリーナを制圧。最後まで走り切った。';$('result-stats').innerHTML=`<div><b>${p.score.toLocaleString()}</b><small>IMPACT SCORE</small></div><div><b>${p.kills}</b><small>WRECKS</small></div><div><b>${Math.max(best,p.score).toLocaleString()}</b><small>BEST</small></div>`;$('resume').classList.add('hidden');$('modal').classList.remove('hidden');}
function finishRacing(){const p=world.cars[0],order=racingRanking(world),place=order.findIndex(c=>c.id===0)+1,points=racingPoints(p);let best=0;try{best=Number(localStorage.getItem('break-cars-racing-best')||0);if(points.total>best)localStorage.setItem('break-cars-racing-best',String(points.total));}catch{}$('result-kicker').textContent='WRECKING RACING / TOTAL RANK';$('result-title').textContent=place===1?'WRECKING CHAMPION':`総合 ${place}位 / ${COUNT}台`;$('result-detail').textContent=`${p.finished?`走行順位 ${p.finishOrder}位`:`未完走 ${p.lap}/${TRACK.laps}周${p.dead?'・大破':''}`} ／ 衝突 ${p.score} ＋ 周回 ${points.lapPoints} ＋ 完走 ${points.finishPoints}`;$('result-stats').innerHTML=`<div><b>${points.total.toLocaleString()}</b><small>TOTAL POINTS</small></div><div><b>${p.kills}</b><small>WRECKS</small></div><div><b>${Math.max(best,points.total).toLocaleString()}</b><small>BEST</small></div>`;$('race-results').innerHTML='<table><thead><tr><th>総合</th><th>CAR / 完走</th><th>衝突</th><th>周回＋完走</th><th>合計</th></tr></thead><tbody>'+order.map((c,i)=>{const t=racingPoints(c);return `<tr class="${c.id===0?'you':''}"><td>${i+1}</td><td>${c.id===0?'YOU':String(c.id+1).padStart(2,'0')} / ${c.finished?c.finishOrder+'位':c.dead?'WRECK':c.lap+'周'}</td><td>${c.score}</td><td>${t.lapPoints+t.finishPoints}</td><td>${t.total}</td></tr>`;}).join('')+'</tbody></table>';$('race-results').classList.remove('hidden');$('resume').classList.add('hidden');$('modal').classList.remove('hidden');}
const pool=[];const particleGeo=new THREE.IcosahedronGeometry(1,0),sparkMat=new THREE.MeshBasicMaterial({color:0xffc05a}),flameMat=new THREE.MeshBasicMaterial({color:0xff542a,transparent:true,opacity:.9,blending:THREE.AdditiveBlending,depthWrite:false}),smokeMat=new THREE.MeshBasicMaterial({color:0x353a3c,transparent:true,opacity:.62,depthWrite:false}),debrisMat=new THREE.MeshStandardMaterial({color:0x24282a,roughness:1,metalness:.35,flatShading:true});for(let i=0;i<320;i++){const mesh=new THREE.Mesh(particleGeo,sparkMat);mesh.visible=false;scene.add(mesh);pool.push({mesh,life:0,max:1,vx:0,vy:0,vz:0,size:.1,kind:'spark'});}let particleIndex=0;function clearParticles(){for(const p of pool){p.life=0;p.mesh.visible=false;}}
function emit(x,y,z,power,kind='spark'){const p=pool[particleIndex++%pool.length];p.kind=kind;p.life=p.max=kind==='smoke'?1.8+Math.random()*1.1:kind==='flame'?.22+Math.random()*.35:kind==='debris'?.8+Math.random()*.9:.35+Math.random()*.65;const spread=kind==='smoke'?1.6:kind==='flame'?power*.18:kind==='debris'?power*.38:power*.56;p.vx=(Math.random()-.5)*spread;p.vy=kind==='smoke'?2+Math.random()*2:kind==='flame'?2.8+Math.random()*4:kind==='debris'?2+Math.random()*power*.28:1+Math.random()*power*.42;p.vz=(Math.random()-.5)*spread;p.size=kind==='smoke'?.34+Math.random()*.25:kind==='flame'?.18+Math.random()*.3:kind==='debris'?.10+Math.random()*.18:.05+Math.random()*.12;p.mesh.material=kind==='smoke'?smokeMat:kind==='flame'?flameMat:kind==='debris'?debrisMat:sparkMat;p.mesh.position.set(x,y,z);p.mesh.scale.setScalar(p.size);p.mesh.visible=true;}
