const skidMesh=new THREE.InstancedMesh(new THREE.PlaneGeometry(.22,.7),new THREE.MeshBasicMaterial({color:0x292924,transparent:true,opacity:.27,depthWrite:false}),1800);skidMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);skidMesh.count=0;skidMesh.frustumCulled=false;scene.add(skidMesh);const dummy=new THREE.Object3D();let skidCount=0,skidClock=0,smokeClock=0;
