 if(mode==='menu'){menuTime+=dt;const a=.35+Math.sin(menuTime*.11)*.25;camTarget.set(p.x+Math.sin(a)*13,7,p.z+Math.cos(a)*13);lookTarget.set(p.x-2.5,1,p.z-2.5);camera.fov=50;}else{camHeading+=angle(p.heading-camHeading)*(1-Math.exp(-4*dt));const speed=Math.hypot(p.vx,p.vz);if(view===2){camTarget.set(p.x,42,p.z-8);lookTarget.set(p.x,0,p.z);camera.fov=65;}else{const distance=view===1?16:9.8;camTarget.set(p.x-Math.sin(camHeading)*distance,view===1?10:4.8+speed*.015,p.z-Math.cos(camHeading)*distance);lookTarget.set(p.x+Math.sin(camHeading)*4,1.1,p.z+Math.cos(camHeading)*4);camera.fov=58+speed*.18;}}camera.position.lerp(camTarget,1-Math.exp(-6*dt));smoothLook.lerp(lookTarget,1-Math.exp(-9*dt));if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake;shake=Math.max(0,shake-dt*1.8);}camera.lookAt(smoothLook);camera.updateProjectionMatrix();$('flash').style.opacity=String(clamp((.25-(world.time-p.hitAt))*2,0,.45));
 uiClock+=dt;if(uiClock>.1){uiClock=0;const p=player;$('alive').innerHTML=`${world.mode==='racing'?trackPosition(world).findIndex(c=>c.id===0)+1:world.cars.filter(c=>!c.dead).length}<span>/${COUNT}</span>`;$('score').textContent=String(p.score).padStart(5,'0');const remain=Math.max(0,Math.ceil((world.mode==='racing'?world.endAt:DURATION)-world.time));$('time').textContent=`${Math.floor(remain/60)}:${String(remain%60).padStart(2,'0')}`;const hp=Math.ceil(p.hp/p.maxHP*100);$('hp').textContent=hp+'%';$('hp-bar').style.width=hp+'%';$('hp-bar').style.background=hp<30?'#ff6945':hp<60?'#edc271':'#74dcc2';for(const part of ['front','left','rear','right'])$(part).style.color=cPartColor(p.parts[part]);$('speed').querySelector('b').textContent=Math.round(Math.hypot(p.vx,p.vz)*3.6);if(world.mode==='racing'){$('race-lap').textContent=p.finished?'FINISHED':p.dead?'WRECKED':`LAP ${Math.min(p.lap+1,TRACK.laps)} / ${TRACK.laps}`;$('race-total').textContent=`${racingPoints(p).total.toLocaleString()} PTS`;$('race-state').textContent=spectating?`CAR ${String(spectatorCarId(p,world)).padStart(2,'0')} を観戦中`:p.wrongWay>.8?'逆走！ 進行方向に戻ろう':world.finishCount>0?'FINAL SPRINT — 先頭がゴール':'衝突＋周回＋完走順位で勝負';$('recover').disabled=p.dead||p.finished||world.time-p.recoveryAt<5;}drawRadar();}
