function spectatorCarId(p,w){return(trackPosition(w).find(c=>!c.dead&&!c.finished)||p).id+1;}
function cPartColor(v){return v<30?'#ff6945':v<60?'#edc271':'#74dcc2';}function drawRadar(){const ctx=$('radar').getContext('2d'),p=world.cars[0];ctx.clearRect(0,0,160,160);ctx.fillStyle='#10203099';ctx.strokeStyle='#9badbd66';ctx.lineWidth=2;const racing=world.mode==='racing',scale=racing?.87:69/RADIUS;ctx.beginPath();if(racing){for(let i=0;i<=96;i++){const q=trackPoint(i/96*LENGTH);if(i===0)ctx.moveTo(80+q.x*scale,80+q.z*scale);else ctx.lineTo(80+q.x*scale,80+q.z*scale);}ctx.lineWidth=15;ctx.strokeStyle='#67778488';ctx.stroke();ctx.lineWidth=1;ctx.strokeStyle='#afbfcc99';}else ctx.arc(80,80,74,0,Math.PI*2);ctx.fill();ctx.stroke();for(const c of world.cars){if(c.finished)continue;const x=80+c.x*scale,y=80+c.z*scale;if(c.dead){ctx.strokeStyle='#ff6148';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-3.2,y-3.2);ctx.lineTo(x+3.2,y+3.2);ctx.moveTo(x+3.2,y-3.2);ctx.lineTo(x-3.2,y+3.2);ctx.stroke();continue;}ctx.fillStyle=c.id===0?'#ff9263':'#dce4e9';ctx.beginPath();ctx.arc(x,y,c.id===0?4:2.6,0,Math.PI*2);ctx.fill();if(c.id===0){ctx.strokeStyle='#ff9263';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+Math.sin(p.heading)*10,y+Math.cos(p.heading)*10);ctx.stroke();}}}
