function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;if(mode==='countdown'){const old=Math.ceil(count);count-=dt;const next=Math.ceil(count);$('countdown').textContent=count>0?String(Math.max(1,next)):'GO';if(next!==old&&next>=0)sound(next===0?880:440,true);if(count<=0){mode='race';toast(world.mode==='racing'?'4周！ 追い抜け、ぶつけろ。':'側面を狙え。生き残れ。',2);}}else if(mode==='race'){$('countdown').textContent='';accumulator+=dt;while(accumulator>=1/60){step(world,input);events();accumulator-=1/60;if((world.mode!=='racing'&&world.cars[0].dead)||world.done){finish();break;}}if(world.mode!=='racing'&&world.time-world.cars[0].lastContact>17&&toastTime<=0)toast(world.time-world.cars[0].lastContact>22?'NO CONTACT — 耐久力低下':'接触しろ！ 失格警告',1);}if(mode!=='paused'){if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').textContent='';}visuals(dt);}else if(engineGain)engineGain.gain.setTargetAtTime(0,audioCtx.currentTime,.05);renderer.render(scene,camera);}
